script:
(function () {
  'use strict';
  // Asset allocation illustrator. Nothing here is a recommendation: returns and bad-year changes are
  // user-editable hypothetical assumptions.
  //   weight of a class = its value / portfolio total (current mix) or the target %
  //   blended return R = sum of weight x hypothetical return (a mix rebalanced back to its weights)
  //   projection: monthly rate (1 + R)^(1/12) - 1, monthly additions at the end of each month
  //   bad year = sum of weight x hypothetical bad-year change, applied to today's total
  //   rebalance change = target % x total - current value (the changes always net to $0)
  // Checked in Node (aa.test.js): 60/30/10 at 7/4/2% blends to 5.6%; default current mix
  // 70k/22k/8k blends to 5.94%; $100,000 + $500/month at 5.6% for 20 years matches the closed form
  // 100000 x 1.056^20 + 500 x ((1 + j)^240 - 1) / j with j = 1.056^(1/12) - 1; bad year of
  // 60/30/10 at -30/-5/0% = -19.5%; rebalance changes sum to $0; 0% returns = plain sum.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var KEYS = ['S', 'B', 'C', 'O'];
  var NAMES = { S: 'Stocks', B: 'Bonds', C: 'Cash', O: 'Other assets' };
  var OUTPUTS = ['aaTgtFuture', 'aaCurFuture', 'aaTotal', 'aaTgtReturn', 'aaCurReturn', 'aaAdded', 'aaTgtBad', 'aaCurBad', 'aaMoved'];

  // --- calc start
  function blend(weights, values) {
    var s = 0;
    for (var k = 0; k < weights.length; k++) s += weights[k] * values[k];
    return s;
  }

  function project(start, monthly, annualRate, years) {
    var j = Math.pow(1 + annualRate, 1 / 12) - 1, bal = start, rows = [];
    for (var m = 1; m <= years * 12; m++) {
      bal = bal * (1 + j) + monthly;
      if (m % 12 === 0) rows.push(bal);
    }
    return rows;
  }

  function rebalance(current, targetWeights) {
    var total = current.reduce(function (a, b) { return a + b; }, 0);
    return current.map(function (v, k) { return targetWeights[k] * total - v; });
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 2 : d).replace(/\.?0+$/, '').replace('-', '−') + '%'; }

  function signed(x) { return Math.abs(x) < 0.5 ? '$0' : (x > 0 ? '+' : '−') + money.format(Math.abs(x)); }

  function fail(msg) {
    var error = document.getElementById('aaError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('aaRebalance').innerHTML = '';
    document.getElementById('aaProjection').innerHTML = '';
    document.getElementById('aaNote').hidden = true;
  }

  function update() {
    document.getElementById('aaError').hidden = true;
    var cur = KEYS.map(function (k) { return num('aaCur' + k); }),
        tgt = KEYS.map(function (k) { return num('aaTgt' + k); }),
        ret = KEYS.map(function (k) { return num('aaRet' + k); }),
        bad = KEYS.map(function (k) { return num('aaBad' + k); });
    var monthly = num('aaMonthly'), years = num('aaYears');
    var sumT = tgt.reduce(function (a, b) { return a + (isNaN(b) ? 0 : b); }, 0);
    document.getElementById('aaTargetSum').textContent = 'Target mix total: ' + (Math.round(sumT * 100) / 100) + '%';
    var all = cur.concat(tgt, ret, bad, [monthly, years]);
    if (all.some(isNaN)) return fail('Fill in every box with a number (0 is fine).');
    if (cur.some(function (v) { return v < 0; }) || monthly < 0) return fail('Values and additions cannot be negative.');
    if (tgt.some(function (v) { return v < 0 || v > 100; })) return fail('Each target must be from 0 to 100%.');
    if (Math.abs(sumT - 100) > 0.01) return fail('The target mix adds up to ' + (Math.round(sumT * 100) / 100) + '%. Adjust it to total 100%.');
    if (ret.some(function (v) { return v < -50 || v > 50; })) return fail('Enter hypothetical returns from -50% to 50%.');
    if (bad.some(function (v) { return v < -100 || v > 100; })) return fail('Enter bad-year changes from -100% to 100%.');
    years = Math.round(years);
    if (years < 1 || years > 60) return fail('Enter 1 to 60 years to project.');
    var total = cur.reduce(function (a, b) { return a + b; }, 0);
    if (total <= 0 && monthly <= 0) return fail('Enter a current value or a monthly addition.');

    var tW = tgt.map(function (v) { return v / 100; });
    var cW = total > 0 ? cur.map(function (v) { return v / total; }) : tW.slice();
    var rD = ret.map(function (v) { return v / 100; }), bD = bad.map(function (v) { return v / 100; });
    var tR = blend(tW, rD), cR = blend(cW, rD), tBad = blend(tW, bD), cBad = blend(cW, bD);
    var tRows = project(total, monthly, tR, years), cRows = project(total, monthly, cR, years);
    var moves = rebalance(cur, tW);
    var moved = moves.reduce(function (a, m) { return a + (m > 0 ? m : 0); }, 0);

    document.getElementById('aaTgtFuture').textContent = money.format(tRows[tRows.length - 1]);
    document.getElementById('aaCurFuture').textContent = money.format(cRows[cRows.length - 1]);
    document.getElementById('aaTotal').textContent = money.format(total);
    document.getElementById('aaTgtReturn').textContent = pct(tR);
    document.getElementById('aaCurReturn').textContent = pct(cR);
    document.getElementById('aaAdded').textContent = money.format(monthly * 12 * years);
    document.getElementById('aaTgtBad').textContent = signed(tBad * total) + ' (' + pct(tBad, 1) + ')';
    document.getElementById('aaCurBad').textContent = signed(cBad * total) + ' (' + pct(cBad, 1) + ')';
    document.getElementById('aaMoved').textContent = money.format(moved);
    var note = document.getElementById('aaNote');
    note.hidden = total > 0;
    note.textContent = 'With no current holdings, the current mix is treated as the target mix.';

    document.getElementById('aaRebalance').innerHTML = KEYS.map(function (k, idx) {
      return '<tr><th scope="row">' + NAMES[k] + '</th><td>' + money.format(cur[idx]) + '</td><td>' +
             (total > 0 ? pct(cW[idx], 1) : '–') + '</td><td>' + pct(tW[idx], 1) + '</td><td>' +
             money.format(tW[idx] * total) + '</td><td>' + signed(moves[idx]) + '</td></tr>';
    }).join('');
    document.getElementById('aaProjection').innerHTML = tRows.map(function (t, idx) {
      var c = cRows[idx];
      return '<tr><td>' + (idx + 1) + '</td><td>' + money.format(monthly * 12 * (idx + 1)) + '</td><td>' +
             money.format(c) + '</td><td>' + money.format(t) + '</td><td>' + signed(t - c) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('aaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
